import {state,esc,dateKey} from '../../lib/store.js';
import {getTaskCategories,getTaskCategory,taskStatus,rangeStart,mainProgress} from '../../lib/progress/model.js';
import {input,area} from '../pixel/primitives.js';
import {action,box,glyph,cat,meter,categoryBadge,categoryIcon,titleHeader} from './shared.js';

const tabLabels={TODAY:'今天',UPCOMING:'即将开始',SOMEDAY:'待定',DONE:'已完成'};
const typeLabels={MAIN:'主线',SIDE:'支线',DAILY:'日常',NORMAL:'普通'};
const categoryOptions=()=>getTaskCategories(state);

export function questForm(id='',type='DAILY'){
 const t=state.tasks.find(task=>String(task.id)===String(id))||{questType:type,category:'thesis',status:'TODAY',dueDate:dateKey()};
 const options=(name,label,values,value)=>`<label class="field"><span>${label}</span><select name="${name}">${values.map(([key,text])=>`<option value="${esc(key)}" ${value===key?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 return `<form data-form="quest" data-id="${esc(id)}" class="quest-form">${input('title','任务标题',t.title||'','text','required maxlength="240"')}<div class="formgrid">${options('category','任务分类',categoryOptions().map(category=>[category.id,category.label]),t.category)}${options('questType','任务类型',[['MAIN','主线 / +50 经验'],['SIDE','支线 / +20 经验'],['DAILY','日常 / +10 经验']],t.questType)}${input('dueDate','截止日期',t.dueDate||'','date')}${input('estimatedMinutes','预计分钟',t.estimatedMinutes??'','number','min="1" max="1440" step="1"')}${options('status','任务阶段',[['TODAY','今天'],['UPCOMING','即将开始'],['SOMEDAY','待定']],t.done?t.resumeStatus||'TODAY':t.status)}${options('parentTaskId','关联主线任务（可选）',[['','无'],...state.tasks.filter(task=>task.questType==='MAIN'&&String(task.id)!==String(id)).map(task=>[String(task.id),task.title])],String(t.parentTaskId||''))}</div>${area('note','备注',t.note||'')}<div class="actions"><button class="mc-button primary" type="submit">保存任务</button>${action('取消','close')}</div></form>`;
}

function taskRow(t){
 return `<div class="quest-row ${t.done?'is-done':''}"><span class="quest-check"><input type="checkbox" aria-label="${t.done?'恢复':'完成'} ${esc(t.title)}" data-change="task" data-id="${esc(t.id)}" ${t.done?'checked':''}></span><span class="quest-category-icon" aria-hidden="true">${categoryIcon(t.category)}</span><div class="quest-name"><button type="button" data-action="quest-edit" data-id="${esc(t.id)}">${esc(t.title)}</button>${t.parentTaskId?'<small>支线任务</small>':''}</div>${categoryBadge(t.category)}<span class="quest-date">${t.dueDate===dateKey()?'今天':esc(t.dueDate?.slice(5)||'—')}</span><span class="quest-duration">${t.estimatedMinutes?esc(t.estimatedMinutes)+' 分钟':'—'}</span><span class="quest-type" title="${esc(typeLabels[t.questType]||t.questType)}">${glyph(t.questType==='MAIN'?'star':'flag',16)}</span>${action('···','quest-menu',`data-id="${esc(t.id)}" aria-label="任务菜单 ${esc(t.title)}"`,'tiny')}</div>`;
}

export function questMenu(id){
 const t=state.tasks.find(task=>String(task.id)===String(id));if(!t)return '';
 return `<h3>${esc(t.title)}</h3><p>${categoryBadge(t.category)} · ${esc(typeLabels[t.questType]||t.questType)}</p><p class="pre">${esc(t.note||'没有备注')}</p><p>${esc(t.dueDate||'无截止日期')} / ${t.estimatedMinutes||'—'} 分钟</p><div class="actions">${action('编辑','quest-edit',`data-id="${esc(t.id)}"`)}${action(t.done?'重新打开':'完成任务','quest-toggle',`data-id="${esc(t.id)}"`)}${!t.done?action('设为主线任务','quest-main',`data-id="${esc(t.id)}"`):''}${action('删除','quest-delete',`data-id="${esc(t.id)}"`,'danger')}</div>`;
}

export function categoryManager(){
 const rows=categoryOptions().map(category=>category.builtIn?`<div class="category-manager-row"><span>${categoryIcon(category.id)}<b>${esc(category.label)}</b></span><small>内置分类</small></div>`:`<form class="category-manager-row" data-form="task-category-rename" data-id="${esc(category.id)}"><span>${categoryIcon(category.id)}<input name="label" value="${esc(category.label)}" required maxlength="24" aria-label="分类名称"></span><div class="actions"><button class="mc-button" type="submit">重命名</button>${action('删除','task-category-delete',`data-id="${esc(category.id)}"`,'danger')}</div></form>`).join('');
 return `<p class="muted small">分类只保存在当前本地用户中。删除自定义分类前，需要为相关任务选择新的分类。</p><div class="category-manager">${rows}</div>${action('+ 新建分类','task-category-new','','primary')}`;
}
export function categoryCreateForm(){return `<form data-form="task-category-create">${input('label','分类名称','','text','required maxlength="24"')}<div class="actions"><button class="mc-button primary" type="submit">创建分类</button>${action('取消','close')}</div></form>`}
export function categoryReassignForm(categoryId){const category=getTaskCategory(state,categoryId),count=state.tasks.filter(task=>task.category===categoryId).length,targets=categoryOptions().filter(item=>item.id!==categoryId);return `<p>“${esc(category.label)}”下有 ${count} 条任务。删除分类不会删除任务，请选择新的分类。</p><form data-form="task-category-delete" data-id="${esc(categoryId)}"><label class="field"><span>移动任务到</span><select name="replacement" required>${targets.map(item=>`<option value="${esc(item.id)}">${esc(item.label)}</option>`).join('')}</select></label><div class="actions">${action('取消','close')}<button class="mc-button danger" type="submit">删除并重新分配</button></div></form>`}

function calendar(ui){
 const ym=ui.missionMonth||dateKey().slice(0,7),[y,m]=ym.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7,count=new Date(y,m,0).getDate();
 return box(`${glyph('calendar',17)} 日历 // ${y}年${m}月`,`<div class="quest-calendar">${['一','二','三','四','五','六','日'].map(day=>`<span>${day}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=ym+'-'+String(i+1).padStart(2,'0'),has=state.tasks.some(task=>task.dueDate===d);return `<button type="button" class="${d===dateKey()?'today':''} ${d===ui.questDate?'selected':''}" data-action="quest-date" data-value="${d}" aria-label="查看 ${d} 任务">${i+1}${has?'<i></i>':''}</button>`}).join('')}</div>${ui.questDate?action('清除日期筛选','quest-date','data-value=""','micro'):''}`,`<div>${action('‹','mission-month','data-value="-1" aria-label="上个月"','tiny')}${action('›','mission-month','data-value="1" aria-label="下个月"','tiny')}</div>`);
}

function mainQuest(){
 const main=state.tasks.find(task=>String(task.id)===String(state.mainQuestId)&&!task.done&&task.questType==='MAIN')||state.tasks.find(task=>task.questType==='MAIN'&&!task.done);
 if(!main)return box(`${glyph('star',17)} 主线任务`,`<p class="mc-empty">暂无主线任务</p>${action('设置主线任务','quest-new','data-type="MAIN"')}`);
 const {children,percent}=mainProgress(state,main);return box(`${glyph('star',17)} 主线任务`,`<h3 class="main-quest-title">${esc(main.title)}</h3><div class="mc-progress-line">${meter(percent,'主线子任务完成进度')}<span>${percent}%</span></div>${children.length?children.slice(0,4).map(task=>`<label class="quest-child"><input type="checkbox" data-change="task" data-id="${esc(task.id)}" ${task.done?'checked':''}>${esc(task.title)}</label>`).join(''):'<p class="micro muted">在子任务中选择“关联主线任务”，进度将自动计算。</p>'}`,action('编辑','quest-edit',`data-id="${esc(main.id)}"`,'tiny'));
}

function weekly(){const categories=categoryOptions(),done=state.tasks.filter(task=>task.done&&task.completedAt&&dateKey(task.completedAt)>=rangeStart('week')&&dateKey(task.completedAt)<=dateKey()),max=Math.max(1,...categories.map(category=>done.filter(task=>task.category===category.id).length));return box(`${glyph('chart',17)} 统计 // 本周`,categories.map(category=>{const n=done.filter(task=>task.category===category.id).length;return `<div class="mc-stat-row cat-${esc(category.id)}"><span>${esc(category.label)}</span>${meter(n/max*100,category.label)}<span>${n}</span></div>`}).join('')+'<p class="micro muted">本周完成任务数量</p>')}

export function mission(ui){
 const tab=ui.questTab||'TODAY',categories=categoryOptions(),today=state.tasks.filter(task=>task.dueDate===dateKey()||taskStatus(task)==='TODAY'),done=state.tasks.filter(task=>task.done),list=state.tasks.filter(task=>(ui.questDate?task.dueDate===ui.questDate:taskStatus(task)===tab)&&(!ui.questCategory||task.category===ui.questCategory)).sort((a,b)=>tab==='DONE'?(b.completedAt||'').localeCompare(a.completedAt||''):(a.dueDate||'9999').localeCompare(b.dueDate||'9999')),progress=state.tasks.length?Math.round(done.length/state.tasks.length*100):0;
 const summary=[['focus','今日任务',today.filter(task=>task.done).length+' / '+today.length],['star','主线任务',state.tasks.filter(task=>!task.done&&task.questType==='MAIN').length+' 个进行中'],['mission','支线任务',state.tasks.filter(task=>!task.done&&task.questType==='SIDE').length+' 个进行中'],['chart','总进度',progress+'%']];
 return `${titleHeader('任务中心','任务管理中心','规划今天。<br>专注明天。')}<div class="mission-body"><div class="mission-left"><div class="quest-toolbar"><div class="quest-tabs">${['TODAY','UPCOMING','SOMEDAY','DONE'].map(key=>action(tabLabels[key],'quest-tab',`data-value="${key}" aria-pressed="${tab===key}"`,tab===key?'active':'')).join('')}</div><div class="quest-toolbar-actions">${action('管理分类','task-category-manage')}${action('+ 新建任务 '+cat(),'quest-new','','primary')}</div></div><div class="quest-summary">${summary.map(([g,label,value])=>`<div>${glyph(g,26)}<span>${label}<b>${value}</b></span></div>`).join('')}</div><section class="quest-list"><div class="quest-list-head"><h2>${glyph('sun',21)} ${ui.questDate||tabLabels[tab]}</h2><span class="micro">${list.length} 条任务</span></div><div class="quest-filters">${action('全部','quest-category','data-value=""',!ui.questCategory?'active':'')}${categories.map(category=>action(category.label,'quest-category',`data-value="${esc(category.id)}"`,ui.questCategory===category.id?'active':'')).join('')}</div>${list.map(taskRow).join('')||'<div class="mc-empty">暂无任务<br><small>为今天写下一个小小的目标。</small></div>'}</section></div><aside class="mission-right">${calendar(ui)}${mainQuest()}${weekly()}${box('最近完成',done.filter(task=>task.completedAt).sort((a,b)=>b.completedAt.localeCompare(a.completedAt)).slice(0,4).map(task=>`<button type="button" class="recent-quest" data-action="quest-menu" data-id="${esc(task.id)}"><time>${dateKey(task.completedAt).slice(5)}</time><span>${esc(task.title)}</span><small>${esc(getTaskCategory(state,task.category).label)}</small></button>`).join('')||'<p class="mc-empty">暂无已完成任务</p>',action('查看全部 →','quest-tab','data-value="DONE"','tiny'))}</aside></div>`;
}
